/* Static label token in a pill. Sizing/colours mirror .chip[secondary] so tokens
 * and chips sit together 1:1; the trailing remove button is the only interactive
 * part. */
.tag {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  /* min-height, not height: a fixed one is a promise the content keeps only while it is short.
   * Hand-typed data does not oblige — one tools cell in a real spreadsheet is a whole
   * comma-separated sentence, and as a fixed-height pill it painted its text straight over the
   * tags next to it. The pill grows instead, and the text wraps inside it. */
  min-block-size: var(--control-height-sm);
  padding-block: var(--space-1);
  padding-inline: var(--space-3);
  padding-inline-end: var(--space-2);   /* tighter on the remove side */
  border-radius: var(--radius-full);
  /* Same as .chip, and for the same reason — --secondary is --muted, so on the
   * page the token had no pill. See the note in Chip.css. */
  background: var(--surface-contrast);
  color: var(--secondary-foreground);
  font-size: var(--font-sm);
  font-weight: var(--control-font-weight);
  /* A token is read as one thing, so it keeps its own words together rather than letting one
   * long name break mid-word across the row. */
  overflow-wrap: anywhere;
  max-inline-size: 100%;
}
.tag[data-size="md"] {
  min-block-size: var(--control-height);
  padding-inline: var(--control-padding-x);
  padding-inline-end: var(--space-3);
  font-size: var(--control-font-size);
}
.tag-remove {
  /* 24x24. It had no size at all and took the icon's 16px, which is under the
   * SC 2.5.8 floor and sits hard against the label, so the spacing exception
   * does not rescue it either. The glyph inside is unchanged. */
  inline-size: var(--space-6);
  block-size: var(--space-6);
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-inline-start: var(--space-1);
  padding: 0;
  border: none;
  border-radius: var(--radius-full);
  background: transparent;
  color: inherit;
  opacity: 0.7;
  cursor: pointer;
  transition: opacity var(--duration-fast), background var(--duration-fast);
}
.tag-remove:hover {
  opacity: 1;
  background: color-mix(in oklch, var(--secondary-foreground) 15%, transparent);
}
.tag-remove:active { opacity: 1; background: color-mix(in oklch, var(--secondary-foreground) 25%, transparent); }
/* The ring. It used to trade the outline for that same tint, which is a hover
 * by another name: keyboard focus and the pointer produced identical pixels,
 * and the tint measures ~1.2:1 where SC 2.4.11 asks 3:1. */
.tag-remove:focus-visible {
  opacity: 1;
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
}

import './Tag.css'
import type { ReactNode } from 'react'
import { cn } from '../lib/cn'
import { Icon } from '../Icon'
import { Tooltip } from '../Tooltip'

type Props = {
  children: ReactNode
  /** When set, renders a trailing remove button that calls this on click. */
  onRemove?: () => void
  /** Accessible label + tooltip for the remove button (required when removable). */
  removeLabel?: string
  /** Follows the row it sits in: `sm` inside a cell or a field, `md` on its own. */
  size?: 'sm' | 'md'
  className?: string
}

/* A static, non-interactive label token in a pill — the read-only counterpart to
 * <Chip> (which is a button). Optionally removable: the label does nothing, only
 * the trailing X drops the token, so the remove control can be its own button
 * (a remove button nested inside a Chip button would be invalid HTML). 
   *
   * Copy: the value as the reader wrote or chose it, unaltered. A tag is data;
   * rewording it makes it un-findable.
   */
export function Tag({ children, onRemove, removeLabel, size = 'sm', className }: Props) {
  return (
    <span className={cn('tag', className)} data-size={size}>
      <span className="tag-label">{children}</span>
      {onRemove && (
        <Tooltip content={removeLabel ?? ''}>
          <button type="button" className="tag-remove" aria-label={removeLabel} onClick={onRemove}>
            <Icon name="close" />
          </button>
        </Tooltip>
      )}
    </span>
  )
}
